-- PEGASUS CTF / MySQL 8+. Apply after the platform `users(id)` table exists.
CREATE TABLE ctf_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL UNIQUE, description TEXT NOT NULL, icon VARCHAR(32) NOT NULL, is_linear BOOLEAN NOT NULL DEFAULT TRUE, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_category_active(is_active));
CREATE TABLE ctf_challenges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, public_id CHAR(10) NOT NULL UNIQUE, category_id BIGINT UNSIGNED NOT NULL, prerequisite_id BIGINT UNSIGNED NULL, title VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, difficulty ENUM('easy','medium','hard','expert') NOT NULL, scenario TEXT NOT NULL, learning_objective TEXT NOT NULL, flag_hash VARCHAR(255) NOT NULL, solution LONGTEXT NOT NULL, references_json JSON NOT NULL, base_points SMALLINT UNSIGNED NOT NULL, max_attempts SMALLINT UNSIGNED NOT NULL DEFAULT 20, time_limit_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 60, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_ch_category FOREIGN KEY(category_id) REFERENCES ctf_categories(id), CONSTRAINT fk_ch_prereq FOREIGN KEY(prerequisite_id) REFERENCES ctf_challenges(id) ON DELETE SET NULL, CONSTRAINT chk_points CHECK(base_points BETWEEN 1 AND 5000), INDEX idx_challenge_filter(category_id,difficulty,is_active), FULLTEXT INDEX idx_challenge_search(title,scenario));
CREATE TABLE ctf_hints (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, challenge_id BIGINT UNSIGNED NOT NULL, hint_order TINYINT UNSIGNED NOT NULL, content TEXT NOT NULL, penalty_percent TINYINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(challenge_id,hint_order), CONSTRAINT fk_hint_ch FOREIGN KEY(challenge_id) REFERENCES ctf_challenges(id) ON DELETE CASCADE, CONSTRAINT chk_hint_order CHECK(hint_order BETWEEN 1 AND 3), CONSTRAINT chk_hint_penalty CHECK(penalty_percent BETWEEN 0 AND 100));
CREATE TABLE ctf_resources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, challenge_id BIGINT UNSIGNED NOT NULL, display_name VARCHAR(160) NOT NULL, storage_key VARCHAR(255) NOT NULL UNIQUE, mime_type VARCHAR(100) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, sha256 CHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_resource_ch FOREIGN KEY(challenge_id) REFERENCES ctf_challenges(id) ON DELETE CASCADE, INDEX idx_resource_ch(challenge_id));
CREATE TABLE ctf_user_progress (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, challenge_id BIGINT UNSIGNED NOT NULL, status ENUM('not_started','in_progress','completed') NOT NULL DEFAULT 'not_started', attempts SMALLINT UNSIGNED NOT NULL DEFAULT 0, hints_used TINYINT UNSIGNED NOT NULL DEFAULT 0, started_at TIMESTAMP NULL, completed_at TIMESTAMP NULL, elapsed_seconds INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(user_id,challenge_id), CONSTRAINT fk_progress_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_progress_ch FOREIGN KEY(challenge_id) REFERENCES ctf_challenges(id) ON DELETE CASCADE, INDEX idx_progress_status(user_id,status));
CREATE TABLE ctf_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, challenge_id BIGINT UNSIGNED NOT NULL, submitted_hash CHAR(64) NOT NULL, is_correct BOOLEAN NOT NULL, ip_hash CHAR(64) NOT NULL, user_agent_hash CHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_submission_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_submission_ch FOREIGN KEY(challenge_id) REFERENCES ctf_challenges(id) ON DELETE CASCADE, INDEX idx_submission_rate(user_id,created_at), INDEX idx_submission_challenge(user_id,challenge_id,created_at), INDEX idx_submission_anomaly(ip_hash,created_at));
CREATE TABLE ctf_scores (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, challenge_id BIGINT UNSIGNED NULL, event_type ENUM('solve','first_blood','no_hint','category_bonus','admin_adjustment') NOT NULL, points INT NOT NULL, reason VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_score_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_score_ch FOREIGN KEY(challenge_id) REFERENCES ctf_challenges(id) ON DELETE SET NULL, INDEX idx_score_rank(user_id,created_at));
CREATE TABLE ctf_badges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, icon VARCHAR(80) NOT NULL, criteria_json JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE ctf_user_badges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, badge_id BIGINT UNSIGNED NOT NULL, awarded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(user_id,badge_id), CONSTRAINT fk_ub_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_ub_badge FOREIGN KEY(badge_id) REFERENCES ctf_badges(id) ON DELETE CASCADE);
CREATE TABLE ctf_leaderboards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, period_type ENUM('global','weekly','monthly','category') NOT NULL, period_key VARCHAR(80) NOT NULL, user_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NULL, points INT UNSIGNED NOT NULL, completed_count SMALLINT UNSIGNED NOT NULL, first_bloods SMALLINT UNSIGNED NOT NULL, elapsed_seconds BIGINT UNSIGNED NOT NULL, rank_position INT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(period_type,period_key,user_id,category_id), CONSTRAINT fk_lb_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_lb_cat FOREIGN KEY(category_id) REFERENCES ctf_categories(id) ON DELETE CASCADE, INDEX idx_lb_query(period_type,period_key,rank_position));
CREATE TABLE ctf_activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED NULL, target_user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, metadata_json JSON NOT NULL, ip_hash CHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_log_actor FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT fk_log_target FOREIGN KEY(target_user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_audit(action,created_at), INDEX idx_audit_actor(actor_user_id,created_at));
